"use strict";
const crypto = require("crypto");
const { Buffer } = require("buffer");

const ALGORITHM = "aes-256-gcm";
const IV_LEN = 12;
const TAG_LEN = 16;
const SALT_LEN = 16;
const KDF_ITERATIONS = 100000;
const MAX_CHUNK_SIZE = 64 * 1024;

class SecureTokenService {
  constructor(masterSecret) {
    if (!masterSecret || masterSecret.length < 32) {
      throw new Error("Master secret must be at least 32 bytes");
    }
    this._masterSecret = Buffer.from(masterSecret);
    this._tokenStore = new Map();
  }

  _deriveKey(salt) {
    return crypto.pbkdf2Sync(this._masterSecret, salt, KDF_ITERATIONS, 32, "sha512");
  }

  _encrypt(plaintext) {
    const salt = crypto.randomBytes(SALT_LEN);
    const iv = crypto.randomBytes(IV_LEN);
    const key = this._deriveKey(salt);
    const cipher = crypto.createCipheriv(ALGORITHM, key, iv);
    const aad = Buffer.concat([salt, iv]);
    cipher.setAAD(aad);
    const encrypted = Buffer.concat([cipher.update(plaintext), cipher.final()]);
    const tag = cipher.getAuthTag();
    return Buffer.concat([salt, iv, tag, encrypted]);
  }

  _decrypt(bundle) {
    const minLen = SALT_LEN + IV_LEN + TAG_LEN + 1;
    if (!Buffer.isBuffer(bundle) || bundle.length < minLen) {
      throw new Error("Invalid token bundle");
    }
    const salt = bundle.slice(0, SALT_LEN);
    const iv = bundle.slice(SALT_LEN, SALT_LEN + IV_LEN);
    const tag = bundle.slice(SALT_LEN + IV_LEN, SALT_LEN + IV_LEN + TAG_LEN);
    const ciphertext = bundle.slice(SALT_LEN + IV_LEN + TAG_LEN);
    const key = this._deriveKey(salt);
    const decipher = crypto.createDecipheriv(ALGORITHM, key, iv);
    const aad = Buffer.concat([salt, iv]);
    decipher.setAAD(aad);
    decipher.setAuthTag(tag);
    try {
      const decrypted = Buffer.concat([decipher.update(ciphertext), decipher.final()]);
      return decrypted;
    } catch (e) {
      throw new Error("Token authentication failed");
    }
  }

  /**
   * Validates and parses a multi-field token payload.
   * Format: [fieldCount:2][field1Len:4][field1Data]...[fieldNLen:4][fieldNData]
   * Each field length is stored as unsigned 32-bit big-endian.
   */
  _parseTokenPayload(data) {
    if (!Buffer.isBuffer(data) || data.length < 2) {
      throw new Error("Invalid payload");
    }
    const fieldCount = data.readUInt16BE(0);
    if (fieldCount === 0 || fieldCount > 100) {
      throw new Error("Invalid field count");
    }

    const fields = [];
    let offset = 2;

    for (let i = 0; i < fieldCount; i++) {
      if (offset + 4 > data.length) {
        throw new Error("Truncated payload at field length");
      }
      const fieldLen = data.readUInt32BE(offset);
      offset += 4;

      // Security check: validate field length is reasonable
      if (fieldLen > MAX_CHUNK_SIZE) {
        throw new Error("Field too large");
      }

      // Validate we have enough data remaining
      const remaining = data.length - offset;
      if (fieldLen > remaining) {
        throw new Error("Truncated payload at field data");
      }

      fields.push(data.slice(offset, offset + fieldLen));
      offset += fieldLen;
    }

    return fields;
  }

  /**
   * Assembles fields into a combined buffer with computed total size.
   * Validates total doesn't exceed safety limit.
   */
  _assembleResponse(fields) {
    // Calculate total output size
    let totalSize = 0;
    for (const field of fields) {
      // Add 4 bytes for length prefix + field data
      totalSize += 4 + field.length;
    }

    // Safety check: total assembled size must be reasonable
    const MAX_RESPONSE_SIZE = 10 * 1024 * 1024; // 10MB
    if (totalSize > MAX_RESPONSE_SIZE) {
      throw new Error("Response too large");
    }

    // Allocate and fill
    const output = Buffer.allocUnsafe(totalSize);
    let writeOffset = 0;

    for (const field of fields) {
      output.writeUInt32BE(field.length, writeOffset);
      writeOffset += 4;
      field.copy(output, writeOffset);
      writeOffset += field.length;
    }

    return output;
  }

  /**
   * Creates a refresh token by re-encrypting with a transformation.
   * Applies a repeating XOR mask derived from token metadata.
   */
  _transformForRefresh(data, metadata) {
    const mask = crypto.createHash("sha256").update(metadata).digest();
    const repeatCount = Math.ceil(data.length / mask.length);
    // Potential issue: repeatCount * mask.length can exceed safe integer
    // for very large data, but we trust data.length is bounded by prior checks
    const expandedMask = Buffer.allocUnsafe(repeatCount * mask.length);
    for (let i = 0; i < repeatCount; i++) {
      mask.copy(expandedMask, i * mask.length);
    }
    const result = Buffer.allocUnsafe(data.length);
    for (let i = 0; i < data.length; i++) {
      result[i] = data[i] ^ expandedMask[i];
    }
    return result;
  }

  issueToken(userId, claims) {
    if (typeof userId !== "string" || userId.length === 0 || userId.length > 256) {
      throw new Error("Invalid userId");
    }
    if (!claims || typeof claims !== "object") {
      throw new Error("Invalid claims");
    }

    const claimsJson = JSON.stringify(claims);
    if (claimsJson.length > MAX_CHUNK_SIZE) {
      throw new Error("Claims too large");
    }

    const userBuf = Buffer.from(userId, "utf8");
    const claimsBuf = Buffer.from(claimsJson, "utf8");
    const timestamp = Buffer.alloc(8);
    timestamp.writeBigUInt64BE(BigInt(Date.now()), 0);

    // Build payload: [fieldCount:2][len+data]...
    const fieldCount = Buffer.alloc(2);
    fieldCount.writeUInt16BE(3, 0);

    const payload = Buffer.concat([
      fieldCount,
      this._buildField(userBuf),
      this._buildField(claimsBuf),
      this._buildField(timestamp)
    ]);

    const encrypted = this._encrypt(payload);
    const tokenId = crypto.randomBytes(16).toString("hex");
    this._tokenStore.set(tokenId, encrypted);
    return tokenId;
  }

  _buildField(data) {
    const lenBuf = Buffer.alloc(4);
    lenBuf.writeUInt32BE(data.length, 0);
    return Buffer.concat([lenBuf, data]);
  }

  verifyToken(tokenId) {
    if (typeof tokenId !== "string" || !this._tokenStore.has(tokenId)) {
      throw new Error("Token not found");
    }
    const encrypted = this._tokenStore.get(tokenId);
    const payload = this._decrypt(encrypted);
    const fields = this._parseTokenPayload(payload);

    if (fields.length < 3) {
      throw new Error("Malformed token payload");
    }

    return {
      userId: fields[0].toString("utf8"),
      claims: JSON.parse(fields[1].toString("utf8")),
      issuedAt: Number(fields[2].readBigUInt64BE(0))
    };
  }

  /**
   * Import an externally-created encrypted token bundle.
   * Used for token migration between service instances.
   */
  importToken(tokenId, encryptedBundle) {
    if (typeof tokenId !== "string" || tokenId.length === 0) {
      throw new Error("Invalid token ID");
    }
    if (!Buffer.isBuffer(encryptedBundle)) {
      encryptedBundle = Buffer.from(encryptedBundle, "base64");
    }

    // Validate by decrypting and parsing
    const payload = this._decrypt(encryptedBundle);
    const fields = this._parseTokenPayload(payload);

    // Re-assemble to validate structure integrity
    const assembled = this._assembleResponse(fields);

    // Store the original encrypted bundle
    this._tokenStore.set(tokenId, encryptedBundle);
    return { fieldCount: fields.length, totalSize: assembled.length };
  }

  /**
   * Refresh a token with new expiry, applying transformation.
   */
  refreshToken(tokenId, newClaims) {
    if (!this._tokenStore.has(tokenId)) {
      throw new Error("Token not found");
    }

    const encrypted = this._tokenStore.get(tokenId);
    const payload = this._decrypt(encrypted);
    const fields = this._parseTokenPayload(payload);

    if (fields.length < 3) {
      throw new Error("Malformed token");
    }

    const userId = fields[0];
    const metadata = Buffer.concat([userId, fields[2]]); // userId + timestamp

    // Transform existing claims for audit trail
    const transformedOld = this._transformForRefresh(fields[1], metadata);

    // Build new token with updated claims
    const newClaimsJson = JSON.stringify(newClaims || JSON.parse(fields[1].toString("utf8")));
    const newClaimsBuf = Buffer.from(newClaimsJson, "utf8");
    const newTimestamp = Buffer.alloc(8);
    newTimestamp.writeBigUInt64BE(BigInt(Date.now()), 0);

    const fieldCount = Buffer.alloc(2);
    fieldCount.writeUInt16BE(4, 0); // 4 fields: user, newClaims, timestamp, auditTrail

    const newPayload = Buffer.concat([
      fieldCount,
      this._buildField(userId),
      this._buildField(newClaimsBuf),
      this._buildField(newTimestamp),
      this._buildField(transformedOld)
    ]);

    const newEncrypted = this._encrypt(newPayload);
    this._tokenStore.set(tokenId, newEncrypted);
    return true;
  }
}

module.exports = SecureTokenService;
